import react from '@sayva/eslint-config/react';
import boundaries from '@sayva/eslint-config/boundaries';
import designRules from '@sayva/eslint-config/design-rules';

export default [
  // Generated by tooling/generate-tokens.mjs (DR-15). `eslint --fix` runs in
  // the pre-commit hook, and a fix applied here would be a diff the
  // generator can never reproduce — the regenerate-and-diff test owns this
  // file's contents.
  { ignores: ['src/tokens.ts'] },
  ...react,
  ...boundaries,
  ...designRules,
  {
    // The token generator is a Node CLI, not a component. Only the two
    // globals it actually uses are declared — the rest of the package stays
    // browser-shaped.
    files: ['tooling/**/*.mjs'],
    languageOptions: { globals: { process: 'readonly', console: 'readonly' } },
  },
];
